 await full(page);const region=page.getByRole('region',{name:'Upcoming Charges',exact:true});await region.locator('.upcoming-date-row').click();await expect(region).toContainText('Synthetic future loan');await page.getByRole('button',{name:'Next upcoming details page',exact:true}).click();await page.getByRole('button',{name:'Back to borrower summary',exact:true}).click();
 fail=true;await page.evaluate(async()=>{const {ownerOfflineRepository}=await import('/apps/pwa/src/owner-offline.ts');await ownerOfflineRepository({issuer:'https://securetoken.google.com/clever-oasis-508610-n7',uid:'phase5-independent-owner'}).invalidateReads()});await page.getByRole('button',{name:'Back to borrowers',exact:true}).click();await full(page);await expect(region).toContainText('Unable to load');fail=false;await region.getByRole('button',{name:'Retry Upcoming Charges',exact:true}).click();await expect(region.locator('.upcoming-date-row')).toHaveCount(1);
 expect(await region.locator('button').evaluateAll(buttons=>buttons.every(button=>(button as HTMLButtonElement).type==='button'))).toBe(true);expect(s.writes).toHaveLength(0);expect(s.commandReads.some(path=>path.includes('/upcoming'))).toBe(false);
