for(const width of [320,390,1440])test(`F2 borrower ordered fields/read-only metadata and compact geometry ${width}px`,async({page},info)=>{await page.setViewportSize({width,height:900});const s=await setup(page);await page.getByRole('button',{name:'Add borrower',exact:true}).click();const region=page.getByRole('region',{name:'Borrower record',exact:true});await expect(region.getByRole('button',{name:'Save borrower',exact:true})).toBeVisible();
 const labels=await region.locator('form>label').evaluateAll(es=>es.map(e=>e.childNodes[0]?.textContent?.trim()));expect(labels).toEqual(['Borrower name (Thai)','Creation Date','English name','Preferred Receiving Cash Account','Payer names on slips','Instagram Username','AI Collection Enabled','City','Working Location','Address','Referrer','Borrower Note','Hide from Borrowers List']);
 await expect(region.getByRole('textbox',{name:/^Creation Date(?: \*)?$/})).toHaveCount(0);await expect(region.getByRole('checkbox',{name:'AI Collection Enabled',exact:true})).toBeChecked();await expect(region.getByRole('textbox',{name:/phone|document/i})).toHaveCount(0);
 for(const lang of ['EN','ไทย'] as const){await chooseLanguagePreservingForm(page,lang);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(width);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);await expect(page.locator('main')).not.toContainText(/Loading|Checking/);mkdirSync('test-results/r052-phase5-completion',{recursive:true});await page.screenshot({path:`test-results/r052-phase5-completion/borrower-form-${info.project.name}-${width}-${lang==='EN'?'en':'th'}.png`})}expect(s.writes).toHaveLength(0);
});

test('F2 full detail groups precede contact fields, exact notes/referrer and related navigation remain available',async({page})=>{const s=await setup(page);await full(page);const region=page.getByRole('region',{name:'Borrower record',exact:true});await expect(region).toContainText('Active Loans');await expect(region).toContainText('Closed Loans');await expect(region).toContainText('ผู้แนะนำจำลอง');await expect(region).toContainText(fields.note.trim());const order=await region.evaluate(e=>{const nodes=Array.from(e.querySelectorAll('h3,label'));return nodes.map(n=>n.textContent||'')});expect(order.indexOf('Active Loans')).toBeLessThan(order.findIndex(t=>t.startsWith('Instagram Username')));expect(order.findIndex(t=>t.startsWith('Payer names on slips'))).toBe(order.findIndex(t=>t.startsWith('Preferred Receiving Cash Account'))+1);await expect(region).toContainText('Payer names on slips'+fields.communicationName);await expect(region).not.toContainText('(borrower)');await expect(region.getByRole('region',{name:'Related loans',exact:true})).toBeVisible();expect(s.writes).toHaveLength(0)});

test('F1 durable CAS rejection preserves exact immutable edit and persisted-before-POST payload',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await expect(page.getByRole('option',{name:'Self must not appear',exact:true})).toHaveCount(0);await page.getByRole('textbox',{name:/^Borrower Note(?: \*)?$/}).fill('new exact ไทย');s.status=422;s.holdWrite=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect.poll(()=>!!s.releaseWrite).toBe(true);await expect(page.locator('main')).not.toContainText(/Loading|Checking|Saving/);const command=s.writes[0].body;expect(command).toMatchObject({operation:'borrower.update',targetId:record.id,expectedVersion:record.version,predecessorRequestId:null,receiptId:null,inputs:{note:'new exact ไทย',hidden:null}});expect(s.pendingBeforePosts[0]).toHaveLength(1);expect(s.pendingBeforePosts[0][0].value.command).toEqual(command);expect(s.pendingBeforePosts[0][0].value.domain).toBe('borrower');expect(s.statusReads).toEqual([command.requestId]);s.releaseWrite!();await expect.poll(async()=>(await pending(page))[0]?.sync?.state).toBe('blocked');expect((await pending(page))[0].value.command).toEqual(command);await page.getByRole('button',{name:'Back to borrowers',exact:true}).click();await openSaved(page);await page.getByRole('button',{name:'View failure details',exact:true}).click();await expect(page.locator('main')).toContainText('new exact ไทย');await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible();expect(s.writes).toHaveLength(1);expect((await pending(page))[0].value.command.expectedVersion).toBe(record.version)});

test('F1 durable Unknown is immutable across reload and queue GET reconciliation removes only known applied requests',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower Note(?: \*)?$/}).fill('unknown attempt ไทย');s.lost=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect.poll(()=>s.writes.length).toBe(1);await expect.poll(async()=>(await pending(page))[0]?.sync?.state).toBe('queued');const command=s.writes[0].body;await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toHaveCount(0);expect((await pending(page))[0].value.command).toEqual(command);await page.reload();await openSaved(page);await expect(page.getByRole('region',{name:'Saved unsynced changes',exact:true}).locator('code')).toHaveText(command.requestId);await expect.poll(()=>s.statusReads.length).toBeGreaterThan(1);expect(s.statusReads.every(id=>id===command.requestId)).toBe(true);expect(s.writes).toHaveLength(1);expect((await pending(page))[0].value.command).toEqual(command);s.statusOutcome='applied';const sync=page.getByRole('button',{name:'Sync now',exact:true});/* The automatic reconciliation loop may already be syncing (button reads Syncing…) and can clear the queue before the explicit click lands, so click only while the queue is non-empty and the button is enabled; the poll below is the contract. */await expect.poll(async()=>(await pending(page)).length===0||await sync.isEnabled().catch(()=>false)).toBe(true);if((await pending(page)).length)await sync.click({timeout:2000}).catch(()=>{});await expect.poll(async()=>(await pending(page)).length).toBe(0);expect(s.statusReads.every(id=>id===command.requestId)).toBe(true);expect(s.writes).toHaveLength(1)});

test('F12 pending storage failure sends no operation and leaves exact unsent fields editable',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower Note(?: \*)?$/}).fill('not sent ไทย');await page.evaluate(()=>{const original=IDBObjectStore.prototype.put;(window as any).originalPut=original;IDBObjectStore.prototype.put=function(value:any,...rest:any[]){if(value.kind==='pending')throw new DOMException('Synthetic quota','QuotaExceededError');return original.call(this,value,...rest)}});await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect(page.getByText('Request was not sent. Device storage is unavailable or full.',{exact:true})).toBeVisible();expect(s.writes).toHaveLength(0);expect(await pending(page)).toHaveLength(0);await expect(page.getByRole('textbox',{name:/^Borrower Note(?: \*)?$/})).toHaveValue('not sent ไทย');await expect(page.getByRole('button',{name:'Save borrower',exact:true})).toBeEnabled();await page.evaluate(()=>{IDBObjectStore.prototype.put=(window as any).originalPut});});

test('F12 restored Unknown rejection retains original CAS and exact inputs without replay or silent rebase',async({page})=>{const s=await setup(page);await full(page);await page.getByRole('button',{name:'Edit borrower',exact:true}).click();await page.getByRole('textbox',{name:/^Borrower Note(?: \*)?$/}).fill('preserved rejected draft');s.lost=true;await page.getByRole('button',{name:'Save borrower',exact:true}).click();await expect.poll(()=>s.writes.length).toBe(1);await expect.poll(async()=>(await pending(page))[0]?.sync?.state).toBe('queued');const command=s.writes[0].body;s.statusOutcome='rejected';await page.reload();await openSaved(page);await expect.poll(async()=>(await pending(page))[0]?.sync?.state).toBe('blocked');await page.getByRole('button',{name:'View failure details',exact:true}).click();await expect(page.locator('main')).toContainText('preserved rejected draft');await expect(page.getByRole('button',{name:'Edit borrower',exact:true})).toBeVisible();expect((await pending(page))[0].value.command).toEqual(command);expect(command.expectedVersion).toBe(record.version);expect(s.statusReads.every(id=>id===command.requestId)).toBe(true);expect(s.writes).toHaveLength(1)});


