async function loanForm(page:Page){await page.locator('.borrower-tile-main').click();await page.getByRole('button',{name:'New loan',exact:true}).click();await expect(page.getByRole('button',{name:'Save loan',exact:true})).toBeEnabled()}
function loanMoneyC(page:Page,label:string){return page.locator('label').filter({has:page.locator('.field-title').filter({hasText:new RegExp('^'+label+'$')})}).getByRole('textbox')}
async function loanValues(page:Page){await loanMoneyC(page,'Principal Amount').fill('100');await loanMoneyC(page,'Transfer Fee').fill('2');await page.getByRole('combobox',{name:/^Disbursing Cash Account(?: \*)?$/}).selectOption('C-account');await page.getByRole('radio',{name:'Daily interest',exact:true}).check();await page.getByRole('textbox',{name:/^Current Daily Interest(?: \*)?$/}).fill('5');await page.getByRole('textbox',{name:/^Loan Arrangement(?: \*)?$/}).fill('exact ไทย arrangement')}

test('F4 UI three loan types preserve conditional source fields and strict320 EN/Thai input geometry',async({page},info)=>{await page.setViewportSize({width:320,height:900});const s=await setup(page);await loanForm(page);const region=page.getByRole('region',{name:'Loan form',exact:true});await expect(page.getByLabel(/^Loan Date(?: \*)?$/)).toHaveValue('2026-10-09');await expect(page.getByRole('checkbox',{name:'Auto Charge Enabled',exact:true})).toBeChecked();await loanValues(page);await expect(page.getByRole('textbox',{name:/^Interest Payment Interval(?: \*)?$/})).toHaveValue('1');await expect(page.getByLabel(/^Due Date(?: \*)?$/)).toHaveCount(0);await expect(region).toContainText('Interest Schedule Anchor Date');
 await page.getByRole('radio',{name:'Daily instalment',exact:true}).check();await expect(page.getByLabel(/^Due Date(?: \*)?$/)).toBeVisible();await expect(page.getByRole('textbox',{name:/^Daily Payment Amount(?: \*)?$/})).toBeVisible();await expect(page.getByRole('textbox',{name:/^Current Daily Interest(?: \*)?$/})).toHaveCount(0);
 await page.getByRole('radio',{name:'Fixed due date',exact:true}).check();await expect(page.getByRole('textbox',{name:/^Fixed Interest(?: \*)?$/})).toBeVisible();await expect(page.getByRole('textbox',{name:/^Interest Payment Interval(?: \*)?$/})).toHaveCount(0);await expect(page.getByRole('textbox',{name:/^Daily Payment Amount(?: \*)?$/})).toHaveCount(0);
 for(const language of ['EN','ไทย'] as const){await chooseLanguagePreservingForm(page,language);expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(320);expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(320);await expect(page.locator('main')).not.toContainText(/Loading|Checking|Saving/);await page.screenshot({path:`test-results/r052-phase5-completion/loan-form-${info.project.name}-320-${language==='EN'?'en':'th'}.png`})}expect(s.writes).toHaveLength(0)});

test('F4 UI loan pending is stored before POST and immutable reload recovery uses only its UUID GET',async({page})=>{const s=await setup(page);await loanForm(page);await loanValues(page);s.lost=true;await page.getByRole('button',{name:'Save loan',exact:true}).click();await expect(page.getByRole('button',{name:'Check loan request',exact:true})).toBeVisible();const command=s.writes[0].body;expect(command).toMatchObject({operation:'loan.create',expectedVersion:null,predecessorRequestId:null,receiptId:null,inputs:{borrowerId:record.id,loanDate:'2026-10-09',principal:'100',transferFee:'2',currentDailyInterest:'5',arrangement:'exact ไทย arrangement',autoChargeEnabled:true}});expect(s.pendingBeforePosts[0][0].value).toMatchObject({domain:'loan',command});const stored=(await pending(page))[0].value;await expect(page.getByRole('button',{name:'Save loan',exact:true})).toHaveCount(0);await expect(loanMoneyC(page,'Principal Amount')).toHaveCount(0);await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await openSaved(page);await expect.poll(()=>s.statusReads.length).toBeGreaterThan(1);expect(s.statusReads.every(id=>id===command.requestId)).toBe(true);expect(s.writes).toHaveLength(1);expect((await pending(page))[0].value).toEqual(stored);await expect(page.getByRole('region',{name:'Saved unsynced changes',exact:true}).locator('code')).toHaveText(command.requestId)});


test('F12 loan pending storage failure sends nothing and retains exact editable source fields',async({page})=>{const s=await setup(page);await loanForm(page);await loanValues(page);await page.evaluate(()=>{const original=IDBObjectStore.prototype.put;(window as any).originalPut=original;IDBObjectStore.prototype.put=function(value:any,...rest:any[]){if(value.kind==='pending')throw new DOMException('Synthetic quota','QuotaExceededError');return original.call(this,value,...rest)}});await page.getByRole('button',{name:'Save loan',exact:true}).click();await expect(page.getByText('Request not sent. Device storage is unavailable or full.',{exact:true})).toBeVisible();expect(s.writes).toHaveLength(0);expect(await pending(page)).toHaveLength(0);await expect(loanMoneyC(page,'Principal Amount')).toHaveValue('100');await expect(page.getByRole('textbox',{name:/^Loan Arrangement(?: \*)?$/})).toHaveValue('exact ไทย arrangement');await expect(page.getByRole('button',{name:'Save loan',exact:true})).toBeEnabled();await page.evaluate(()=>{IDBObjectStore.prototype.put=(window as any).originalPut});});


test('F2 loan account default uses exact holder/active metadata and multiline terms remain compact',async({page})=>{await page.setViewportSize({width:320,height:900});const s=await setup(page);await page.locator('.borrower-tile-main').click();const base={id:'C-account',label:'Synthetic default Lisa',isDefault:true,holderId:'ch:lisa',active:true,holderActive:true};for(const [accounts,expected] of [[[base],'C-account'],[[{...base,isDefault:false}],''],[[base,{...base,id:'C-second'}],''],[[{...base,active:false}],''],[[{...base,holderId:'ch:dad'}],'']] as const){s.loanAccounts=[...accounts];await page.getByRole('button',{name:'New loan',exact:true}).click();await expect(page.getByRole('button',{name:'Save loan',exact:true})).toBeEnabled();await expect(page.getByRole('combobox',{name:/^Disbursing Cash Account(?: \*)?$/})).toHaveValue(expected);const terms=page.getByRole('textbox',{name:/^Loan Arrangement(?: \*)?$/});expect(await terms.evaluate(e=>e.tagName)).toBe('TEXTAREA');await terms.fill('line one\nไทย line two');await expect(terms).toHaveValue('line one\nไทย line two');expect(await page.locator('body').evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(320);await page.getByRole('button',{name:'Back to loan details',exact:true}).click()}expect(s.writes).toHaveLength(0)});


