async function fullLoan(page:Page,s:State){s.loanRows=[{id:'C-loan',borrowerId:record.id,borrowerDisplayName:'Synthetic loan borrower',originalDailyInterestRate:'5',loanDate:'2026-10-06',dueDate:null,closeDate:null,loanType:'ดอกเบี้ยรายวัน',status:'ยังไม่ปิดยอด',principalAmount:'100',outstandingPrincipal:'100',totalPrincipalReceived:'0',totalInterestReceived:'7',totalAmountReceived:'7',defaulted:false,autoChargeEnabled:true}];await page.locator('.borrower-tile-main').click();await page.locator('.loan-record').click();await expect(page.getByRole('button',{name:'Edit loan',exact:true})).toBeVisible()}

test('F6 action held-options double click cannot change confirmation label or payload; only header announces activity',async({page})=>{const s=await setup(page);await fullLoan(page,s);s.holdOptions=true;await page.getByRole('button',{name:'Default Loan',exact:true}).click();await expect.poll(()=>!!s.releaseOptions).toBe(true);await expect(page.getByRole('button',{name:'Generate Charges',exact:true})).toBeDisabled();await expect(page.getByRole('button',{name:'Edit loan',exact:true})).toBeDisabled();await expect(page.locator('.topbar .collection-update')).toContainText('Loading');await expect(page.locator('main')).not.toContainText(/Loading|Checking|Saving/);expect(s.commandReads.filter(p=>p==='/api/loan-options')).toHaveLength(1);s.releaseOptions!();await expect(page.getByRole('heading',{name:'Default Loan',exact:true})).toBeVisible();await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect.poll(()=>s.writes.length).toBe(1);expect(s.writes[0].body).toMatchObject({operation:'loan.default',targetId:loanFullC.id,expectedVersion:loanFullC.version,inputs:{businessDate:'2026-10-09'}});expect(s.pendingBeforePosts[0][0].value).toMatchObject({domain:'loan',recoveryKind:'action',command:s.writes[0].body})});

test('F12 loan action Unknown survives reload and explicit retry keeps identical UUID after status read',async({page})=>{const s=await setup(page);await fullLoan(page,s);await page.getByRole('button',{name:'Generate Charges',exact:true}).click();await expect(page.getByRole('heading',{name:'Generate Charges',exact:true})).toBeVisible();s.lost=true;await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect(page.getByText('Saved on this device. Will sync when connected.',{exact:true})).toBeVisible();await expect.poll(()=>s.writes.length).toBe(1);await expect.poll(()=>s.pendingBeforePosts.length).toBe(1);const cmd=s.writes[0].body;expect(s.pendingBeforePosts[0][0].value).toMatchObject({domain:'loan',recoveryKind:'action',command:cmd});await expect(page.getByRole('button',{name:'Retry same request',exact:true})).toHaveCount(0);await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await openSaved(page);await expect.poll(()=>s.statusReads.length).toBeGreaterThan(1);expect(s.statusReads.every(id=>id===cmd.requestId)).toBe(true);expect(s.writes).toHaveLength(1);expect((await pending(page))[0].value.command).toEqual(cmd);s.lost=false;s.statusOutcome='unresolved';// Automatic sync may reconcile first; either path must reuse the exact request after a status read.
await page.getByRole('button',{name:'Sync now',exact:true}).click({timeout:2000}).catch(()=>{});await expect.poll(()=>s.writes.length).toBe(2);expect(s.writes[1].body).toEqual(cmd);expect(s.statusReads.every(id=>id===cmd.requestId)).toBe(true);await expect.poll(async()=>(await pending(page)).length).toBe(0)});


