test('F12 expense quiet unsent draft survives reload then immutable Unknown recovery keeps immutable pending through automatic status reconciliation',async({page})=>{const s=await setup(page);await openExpensesC(page);await page.getByRole('button',{name:'Add expense',exact:true}).click();await expenseValuesUiC(page);await expect.poll(async()=>(await draftsC(page)).filter(r=>r.value.domain==='expense').length).toBe(1);const row=(await draftsC(page))[0];expect(row.value.draft.fields.amount).toBe('12');await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await openExpensesC(page);await page.getByRole('button',{name:'Add expense',exact:true}).click();await expect(page.getByRole('textbox',{name:/^Amount(?: \*)?$/})).toHaveValue('12');await expect(page.getByRole('textbox',{name:/^Notes(?: \*)?$/})).toHaveValue('expense note ไทย');expect(s.writes).toHaveLength(0);await page.getByRole('button',{name:'Review',exact:true}).click();s.lost=true;await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect(page.getByText('Saved on this device. Will sync when connected.',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Confirm',exact:true})).toHaveCount(0);await expect.poll(()=>s.pendingBeforePosts.length).toBe(1);expect(s.pendingBeforePosts[0][0].value).toMatchObject({domain:'expense',command:s.writes[0].body});await expect.poll(async()=>(await draftsC(page)).filter(r=>r.value.domain==='expense').length).toBe(0);const command=s.writes[0].body;await page.reload();await page.getByRole('button',{name:'Borrowers',exact:true}).filter({visible:true}).click();await expect(page.getByRole('button',{name:'Add borrower',exact:true})).toBeVisible();await openSaved(page);await expect.poll(()=>s.statusReads.length).toBeGreaterThan(1);expect(s.statusReads.every(id=>id===command.requestId)).toBe(true);expect(s.writes).toHaveLength(1);expect((await pending(page))[0].value.command).toEqual(command);await expect(page.getByRole('region',{name:'Saved unsynced changes',exact:true}).locator('code')).toHaveText(command.requestId)});

test('F12 expense pending quota failure sends nothing and retains the unsent draft',async({page})=>{const s=await setup(page);await openExpensesC(page);await page.getByRole('button',{name:'Add expense',exact:true}).click();await expenseValuesUiC(page);await expect.poll(async()=>(await draftsC(page)).length).toBe(1);await page.getByRole('button',{name:'Review',exact:true}).click();await page.evaluate(()=>{const original=IDBObjectStore.prototype.put;(window as any).originalPut=original;IDBObjectStore.prototype.put=function(value:any,...rest:any[]){if(value.kind==='pending')throw new DOMException('Synthetic quota','QuotaExceededError');return original.call(this,value,...rest)}});await page.getByRole('button',{name:'Confirm',exact:true}).click();await expect(page.getByText('The change could not be saved on this device. Keep this page open and try again.',{exact:true})).toBeVisible();expect(s.writes).toHaveLength(0);expect(await pending(page)).toHaveLength(0);expect(await draftsC(page)).toHaveLength(1);await page.evaluate(()=>{IDBObjectStore.prototype.put=(window as any).originalPut})});


